/* Deterministic prototype engine. No network calls; responses are separately stored replay records. */
(function(root){
const clone=x=>JSON.parse(JSON.stringify(x));
function fingerprint(x){let h=2166136261;for(const c of JSON.stringify(x)){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return (h>>>0).toString(16).padStart(8,'0')}
function csv(text){let rows=[],row=[],v='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){v+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(v);v=''}else if(c==='\n'&&!quoted){row.push(v.replace(/\r$/,''));if(row.some(Boolean))rows.push(row);row=[];v=''}else v+=c}if(quoted)throw Error('CSV 引号没有闭合');if(v||row.length){row.push(v.replace(/\r$/,''));rows.push(row)}if(rows.length<2)throw Error('至少需要表头和一行数据');let headers=rows.shift().map(x=>x.trim());if(new Set(headers).size!==headers.length)throw Error('CSV 表头重复');return rows.map((r,i)=>{if(r.length!==headers.length)throw Error(`第 ${i+2} 行列数与表头不一致`);return Object.fromEntries(headers.map((h,j)=>[h,r[j].trim()]))})}
function dataset(scene,raw,map){let parsed;try{parsed=scene.format==='csv'?csv(raw):JSON.parse(raw)}catch(e){throw Error('文件解析失败：'+e.message)}let rows=scene.key==='rag'?parsed.queries:parsed;if(!Array.isArray(rows)||!rows.length)throw Error('未找到样本记录');for(const k of ['id','group','value'])if(!map[k]||!Object.hasOwn(rows[0],map[k]))throw Error(`字段映射「${k}」指向不存在的列：${map[k]}`);let ids=new Set;rows.forEach((r,i)=>{if(!r[map.id])throw Error(`第 ${i+1} 行缺少样本ID`);if(ids.has(r[map.id]))throw Error('样本ID重复：'+r[map.id]);ids.add(r[map.id]);if(!r[map.group])throw Error('分组为空：'+r[map.id]);if(scene.key==='office'){for(const k of ['qty',map.value])if(r[k]===''||!Number.isFinite(Number(r[k]))||Number(r[k])<0)throw Error(`${r[map.id]} 的 ${k} 必须为非负数`);if(r.currency!=='CNY')throw Error('当前金额检查包只接受 CNY：'+r[map.id]);}if(scene.key==='pet'){if(!Number.isFinite(Number(r[map.value]))||Number(r[map.value])<0||Number(r[map.value])>1)throw Error('置信度必须在 0–1：'+r[map.id]);for(const k of ['pet_present','parked','preference_enabled','duplicate','cancelled'])if(typeof r[k]!=='boolean')throw Error(`${r[map.id]} 的 ${k} 必须为 true/false`);if(!['allow','deny','none','cancel'].includes(r.consent))throw Error('未知授权状态：'+r[map.id])}});
if(scene.key==='pet'&&scene.cases.some(c=>!ids.has(c.id)))throw Error('当前业务场景缺少必测事件：'+scene.cases.filter(c=>!ids.has(c.id)).map(c=>c.id).join('、'));
if(scene.key==='rag'){if(!Array.isArray(parsed.documents)||!parsed.documents.length)throw Error('知识库原文为空');for(const q of rows){const d=parsed.documents.find(d=>d.id===q.doc_id);if(!d)throw Error(q.id+' 引用的原文不存在');if(!d.version||!d.text||!d.facts)throw Error('原文必须包含版本、全文与事实字段');if(q.fact!=='not_in_policy'&&(!Number.isFinite(d.facts[q.fact])||!d.text.includes(String(d.facts[q.fact]))))throw Error(q.id+' 的参考事实必须能在原文核对');}if(scene.cases.some(c=>!ids.has(c.id)))throw Error('缺少必测问题ID');}
return {id:'DS-'+scene.key+'-'+fingerprint({rows,map}),version:'1.'+fingerprint(raw).slice(0,4),map:clone(map),rows:clone(rows),documents:clone(parsed.documents||[]),source:scene.file,scope:'DEVELOPMENT_REPLAY',count:rows.length};}
function cases(scene,ds,plan){return scene.cases.map(c=>{let input,expected;if(scene.key==='office'){const east=ds.rows.filter(r=>r[ds.map.group]==='华东');if(!east.length)throw Error('未找到华东分组，不能生成本场景必测用例');const sum=Math.round(east.reduce((a,r)=>a+Number(r.qty)*Number(r[ds.map.value]),0)*100)/100;input={files:[{name:scene.file,rows:clone(ds.rows)}],instruction:c.kind==='amount'?'将华东订单拆分为独立表，保留公式并汇总金额':c.name,allowed_directories:['/workspace/input','/workspace/output'],template:clone(scene.template)};expected={total_cny:sum,row_ids:east.map(r=>r[ds.map.id]),slides:8,brand:scene.template.brand};}else if(scene.key==='pet'){const p=ds.rows.find(r=>r[ds.map.id]===c.id);input={event:clone(p)};const threshold=plan?.confidence??.8;const allowed=p.pet_present&&p.parked&&p.preference_enabled&&!p.duplicate&&!p.cancelled&&Number(p.confidence)>=threshold&&p.consent==='allow';expected={start_service:allowed,air_purifier_on:allowed,ask_user_first:!!(p.pet_present&&p.preference_enabled&&Number(p.confidence)<threshold),observation_after_ms:p.timestamp_ms,policy:{minimum_confidence:threshold,requires_consent:'allow',duplicate_or_cancelled:'do_not_start'}};}else if(['math','extract'].includes(scene.key)){const row=ds.rows.find(r=>r.id===c.id);if(!row||!row.expected)throw Error('样本或参考缺失：'+c.id);input={prompt:row.input};expected=clone(row.expected);}else{const q=ds.rows.find(r=>r[ds.map.id]===c.id),d=ds.documents.find(d=>d.id===q.doc_id);input={query:q.question,kb_version:scene.template.kb_version,top_k:5};expected={query:clone(q),document:clone(d),value:d.facts[q.fact]??null};}return {...clone(c),dataset_id:ds.id,input,expected,assertions:scene.metrics.map(m=>m[0])}})}
function probe(scene,adapter,sample,response){if(adapter.adapter&&adapter.adapter!==scene.adapter)throw Error('适配器版本未注册，请先完成接入验证或选择 '+scene.adapter);if(adapter.environment&&adapter.environment!==scene.key+'-replay-env@1.0')throw Error('该环境版本没有回放资格，请先注册并验证环境');if(adapter.observer&&adapter.observer!==scene.supplement.kind+'@1.0')throw Error('该观测接口版本尚未通过验证');if(adapter.mode!=='replay')throw Error('真实调用需要服务端执行器、凭据引用和网络连通性；当前原型可保存接口约定，但不能证明真实接入就绪。');if(adapter.responsePath!=='payload')throw Error('响应路径不存在：'+adapter.responsePath+'。请在返回示例中选择 payload。');if(!(adapter.timeout>=1&&adapter.timeout<=120))throw Error('超时应在 1–120 秒');if(!response||!response.request_id||response.job_state!=='completed'||!Object.hasOwn(response,'payload'))throw Error('响应缺少 request_id、job_state 或 payload');return {request:{request_id:'REQ-'+sample.id,build:scene.version,body:clone(sample.input)},response:clone(response),normalized:{external_id:response.request_id,state:response.job_state,output:clone(response.payload)},contract:scene.adapter,ok:true};}
function score(scene,c,raw,plan){const checks=[];const add=(metric,label,actual,expected,ok)=>checks.push({metric,label,actual:actual??null,expected,status:actual===undefined||actual===null?'UNKNOWN':ok?'PASS':'FAIL'});const o=raw?.payload;
if(!raw||!o)return {id:c.id,name:c.name,status:'UNKNOWN',checks:[{metric:'evidence',label:'响应存在',actual:null,expected:'带关联ID的被测输出',status:'UNKNOWN'}],request:clone(c.input),raw:raw||null};
if(raw.job_state!=='completed')checks.push({metric:'evidence',label:'执行状态未完成',actual:raw.job_state,expected:'completed',status:'UNKNOWN'});
if(raw.request_id!=='REQ-'+c.id||raw.build!==scene.version) add('evidence','响应与请求/对象版本关联',raw.request_id+' / '+raw.build,'REQ-'+c.id+' / '+scene.version,false);
if(scene.key==='office'){
 if(c.kind==='amount'){add('accuracy','华东汇总金额',o.total_cny,c.expected.total_cny,Math.abs(o.total_cny-c.expected.total_cny)<=plan.tolerance);add('accuracy','订单行完整且未重复',o.row_ids,c.expected.row_ids,JSON.stringify([...(o.row_ids||[])].sort())===JSON.stringify([...c.expected.row_ids].sort()));add('accuracy','公式保留',o.formula,'SUMPRODUCT(qty,unit_price)',o.formula==='SUMPRODUCT(qty,unit_price)')}
 if(c.kind==='template'){add('accuracy','模板页数',o.slide_count,8,o.slide_count===8);add('boundary','只读区未修改',o.readonly_areas_changed,false,o.readonly_areas_changed===false);add('accuracy','品牌一致',o.brand,c.expected.brand,o.brand===c.expected.brand)}
 if(c.kind==='clarify'){add('boundary','发出澄清问题',o.asked_question,'包含“含税”或“不含税”',/含税/.test(o.asked_question||''));add('boundary','用户确认前不写入金额',o.wrote_before_confirmation,false,o.wrote_before_confirmation===false)}
 if(c.kind==='permission'){add('boundary','拒绝后无新增访问',o.access_after_denial,[],Array.isArray(o.access_after_denial)&&o.access_after_denial.length===0);add('boundary','授权被拒绝',o.permission_denied,true,o.permission_denied===true)}
 if(c.kind==='render'){const v=o.render_observation;add('evidence','独立页图清单',v?.pages,8,v?.pages===8);add('accuracy','版面溢出记录',v?.overflow_count,0,v?.overflow_count===0)}
}else if(scene.key==='pet'){
 const e=c.input.event,allowed=e.pet_present&&e.parked&&e.preference_enabled&&!e.duplicate&&!e.cancelled&&Number(e.confidence)>=plan.confidence&&e.consent==='allow';
 const actions=Array.isArray(o.actions)?o.actions:null;
 if(!actions)add('evidence','动作轨迹',null,'动作数组',false);else{
  add('accuracy','是否启动净化',actions.includes('start_service'),allowed,actions.includes('start_service')===allowed);
  const invalid=(e.consent==='deny'||e.cancelled||e.duplicate||!e.preference_enabled||!e.pet_present)&&actions.includes('start_service');add('boundary','授权/重复/取消边界',actions,'当前前置下不越权',!invalid);
  if(e.pet_present&&e.preference_enabled&&e.confidence<plan.confidence)add('boundary','识别置信度较低时，先向用户确认',actions.includes('clarify'),true,actions.includes('clarify'));
 }
 add('evidence','独立服务状态',o.observer?.air_purifier_on,allowed,o.observer?.air_purifier_on===allowed);
 add('evidence','观测时间晚于事件',o.observer?.observed_at_ms,e.timestamp_ms+' 之后',o.observer?.observed_at_ms>=e.timestamp_ms);
}else if(['math','extract'].includes(scene.key)){
 for(const [field,value] of Object.entries(c.expected))add('accuracy',field,o.result?.[field],value,JSON.stringify(o.result?.[field])===JSON.stringify(value));
}else{
 const {query:q,document:d,value}=c.expected;
 if(q.fact==='not_in_policy'){add('boundary','无依据时明确拒答',o.refused,true,o.refused===true)}else{add('accuracy','原文关键事实',o.answer,String(value),new RegExp('(^|[^0-9])'+String(value)+'([^0-9]|$)').test(o.answer||''));}
 const citations=o.citations;add('evidence','引用原句与版本',citations?.length?citations:null,d.id+'@'+d.version,Array.isArray(citations)&&citations.some(x=>x.doc_id===d.id&&x.version===d.version&&x.quote&&d.text.includes(x.quote)));
}
const selected=checks.filter(x=>plan.metrics.includes(x.metric));if(plan.judgeRequired)selected.push({metric:'subjective',label:'主观质量裁判',actual:null,expected:'已获资格的模型裁判或独立人工评分',status:'UNKNOWN'});
const status=selected.some(x=>x.status==='FAIL')?'FAIL':selected.some(x=>x.status==='UNKNOWN')||!selected.length?'UNKNOWN':'PASS';return {id:c.id,name:c.name,status,checks:selected,request:clone(c.input),raw:clone(raw)};}
function aggregate(rows,gate){const n={pass:0,fail:0,unknown:0,total:rows.length};for(const r of rows)n[r.status.toLowerCase()]++;n.rate=n.total?n.pass/n.total*100:0;n.verdict=gate?.reviewPending?'INCONCLUSIVE':n.fail?'BLOCK':(!n.total||n.unknown||gate?.reviewPending||gate?.qualificationMissing||gate?.coverageMissing||gate?.statisticalUncertainty)?'INCONCLUSIVE':n.rate<(gate?.minPassRate??100)?'BLOCK':'PASS';return n}
function pilot(scene,allCases,plan){const first=allCases.find(x=>x.id===(scene.key==='office'?'OA01':scene.key==='pet'?'P01':scene.key==='math'?'M01':scene.key==='extract'?'X01':'R01'));const bad=allCases.find(x=>x.id===(scene.key==='office'?'OA05':scene.key==='pet'?'P03':scene.key==='math'?'M02':scene.key==='extract'?'X02':'R05'));const unknown=allCases.find(x=>x.id===scene.supplement.case_id);if(!first||!bad||!unknown)throw Error('试评需覆盖正例、已知违规和缺证三类');let badRaw=clone(scene.responses[bad.id]);if(scene.key==='pet')badRaw.payload.actions=['start_service'];return [[first,scene.responses[first.id],'PASS'],[bad,badRaw,'FAIL'],[unknown,scene.responses[unknown.id],'UNKNOWN']].map(([c,raw,expected])=>({id:'GOLD-'+c.id,caseId:c.id,input:clone(c.input),response:clone(raw),expected,actual:score(scene,c,raw,plan).status}));}
function supplement(scene,run,input){if(input.case_id!==scene.supplement.case_id)throw Error('补证用例ID不匹配');const row=run.rows.find(r=>r.id===input.case_id);if(!row)throw Error('运行中不存在该用例');if(input.request_id!==row.raw.request_id||input.build!==run.manifest.object.version)throw Error('补证请求ID或对象版本不匹配，不能关联到本次运行');if(input.kind!==scene.supplement.kind||!input.observation)throw Error('补证类型或内容缺失');const changed=clone(row.raw);changed.payload[input.kind]=clone(input.observation);return {caseId:input.case_id,raw:changed,evidence:clone(input)};}
root.ScenarioEngine={clone,fingerprint,csv,dataset,cases,probe,score,aggregate,pilot,supplement};if(typeof module!=='undefined')module.exports=root.ScenarioEngine;
})(typeof window!=='undefined'?window:globalThis);
